(7306366, 1139830, 83149, '<td valign="top">I find that light distracting, otherwise it is a pretty clean shot.</td>', 'I find that light distracting, otherwise it is a pretty clean shot.', '2015-01-24 13:18:26.000000', NULL, 1),
(7306368, 1139999, 83149, '<td valign="top">Nice tells a story, well done.</td>', 'Nice tells a story, well done.', '2015-01-24 13:20:43.000000', NULL, 1),
