(7319183, 1139960, 100831, '<td valign="top">I have no idea where my head was when I viewed/voted this image originally, but I''ll favorite it now! The space and colors are perfectly aligned. Congrats on the deserved blue.</td>', 'I have no idea where my head was when I viewed/voted this image originally, but I''ll favorite it now! The space and colors are perfectly aligned. Congrats on the deserved blue.', '2015-02-21 11:23:45.000000', NULL, 0),
